                        &0u64.to_le_bytes(),
                        &[bump],
                    ],
                    &program_id,
                )
                .ok()
                .map(|key| (key, bump))
            })
            .unwrap();
        assert_ne!(other_page, canonical_page);
        account.key = other_page;
        assert!(crate::history::require_root_page_address_with_bump(
            &program_id,
            &lane_key,
