        )
        .unwrap();
        drop(infos);
        assert_eq!(runtime.calls, 1);

        let lane =
            decode_pool_v1_pair_forest_lane_state_v1(&accounts[1].data, &POOL_V1_PAIR_EMPTY_ROOTS)
                .unwrap();
        assert_eq!(lane.lane_id, lane_id);
        assert_eq!(
