            .map(|account| account.data.clone())
            .collect::<Vec<_>>();
        let infos: Vec<_> = accounts.iter_mut().map(TestAccount::info).collect();
        assert!(process_pair_forest_terminal_with_verifier_v1(
            &program_id,
            &infos,
            &instruction,
            2,
            &Rent::default(),
            &mut no_cpi,
            |_, _, _, _, _, _, _, _, _, _, _| panic!("stale replay reached verifier"),
            |_| {},
        )
        .is_err());
        drop(infos);
        assert_eq!(
            accounts
                .iter()
                .map(|account| account.data.clone())
                .collect::<Vec<_>>(),
            before
        );
    }

    #[test]
    fn one_terminal_withdrawal_authenticates_loader_and_checks_custody_delta_before_writes() {
        let program_id = Pubkey::new_unique();
        let mint = Pubkey::new_unique();
        let (master_key, mut master_state) = master(program_id, mint);
        master_state.identity.asset_mint = mint.to_bytes();
        master_state.identity.token_program = LEGACY_SPL_TOKEN_PROGRAM_ID.to_bytes();
        master_state.has_checkpoint = true;
        master_state.next_checkpoint_sequence = 1;
        let nullifier = digest(2);
        let lane_id =
            aspis_statement::pool_v1::pool_v1_pair_forest_output_lane_v1(&nullifier).unwrap();
        let lane_key = pool_v1_pair_forest_lane_address(&program_id, &master_key, lane_id)
            .unwrap()
            .0;
        let lane = canonical_genesis_lane(&program_id, &master_key, lane_id);
        let (next_tree, _) = lane
            .tree
            .append_one_with_empty_roots(digest(9_100), &POOL_V1_PAIR_EMPTY_ROOTS)
            .unwrap();
        let checkpoint = PoolV1PairForestCheckpointV1 {
            bump: pool_v1_pair_forest_checkpoint_address(&program_id, &master_key, 0).1,
            master: master_key.to_bytes(),
            deployment_domain: master_state.identity.deployment_domain,
            checkpoint_sequence: 0,
            global_root: digest(7_100),
            lane_sequences: [0; 8],
        };
        let checkpoint_key = pool_v1_pair_forest_checkpoint_address(&program_id, &master_key, 0).0;
        let destination = Pubkey::new_unique();
        let request = PoolV1PairForestTerminalRequestV1 {
            verifier_profile: [41; 32],
            verifier_release: [42; 32],
            pool_program: program_id.to_bytes(),
            public: PoolV1PairForestTerminalPaymentV1::Withdrawal(PoolV1WithdrawalPublicV1 {
                pool: master_key.to_bytes(),
                deployment_domain: master_state.identity.deployment_domain,
                anchor_sequence: 0,
                anchor_root: checkpoint.global_root,
                nullifier,
                asset_id: master_state.identity.asset_id,
                amount: 25,
                destination_token_account: destination.to_bytes(),
                change_commitment: digest(300),
            }),
        };
        let result = PoolV1PairForestTerminalResultV1 {
            transition_kind: PoolV1TransitionKind::Withdrawal,
            master_account: master_key.to_bytes(),
            selected_lane_account: lane_key.to_bytes(),
            output_lane: lane_id,
            nullifier,
            verified_afterstate: PoolV1PairVerifiedAfterstateV1 {
                next_pair_index: next_tree.next_leaf_index,
                next_root: next_tree.root,
                next_frontier: next_tree.frontier,
            },
        };
        let marker_key = crate::pool_v1_pair_forest_nullifier_marker_address(
            &program_id,
            &master_key,
            &aspis_statement::encode_digest_canonical(&nullifier),
        )
        .unwrap()
        .0;
        let mut accounts = terminal_base_accounts(
            program_id,
            master_key,
            &master_state,
            checkpoint_key,
            &checkpoint,
            lane_key,
            &lane,
            marker_key,
        );
        let authority = crate::pool_v1_vault_authority_address(&program_id, &master_key).0;
        accounts.extend([
            TestAccount {
                key: mint,
                owner: LEGACY_SPL_TOKEN_PROGRAM_ID,
                lamports: 1,
                data: initialized_mint_data(),
                signer: false,
                writable: false,
                executable: false,
            },
            TestAccount {
                key: crate::pool_v1_vault_token_account_address(&program_id, &master_key).0,
                owner: LEGACY_SPL_TOKEN_PROGRAM_ID,
                lamports: 1,
                data: initialized_token_data(mint, authority, 100),
                signer: false,
                writable: true,
                executable: false,
            },
            TestAccount {
                key: destination,
                owner: LEGACY_SPL_TOKEN_PROGRAM_ID,
                lamports: 1,
                data: initialized_token_data(mint, Pubkey::new_unique(), 10),
                signer: false,
                writable: true,
                executable: false,
            },
            TestAccount {
                key: authority,
                owner: system_program::id(),
                lamports: 0,
                data: vec![],
                signer: false,
                writable: false,
                executable: false,
            },
            TestAccount {
                key: LEGACY_SPL_TOKEN_PROGRAM_ID,
                owner: bpf_loader::id(),
                lamports: 1,
                data: vec![],
                signer: false,
                writable: false,
                executable: true,
            },
        ]);
        let instruction = terminal_instruction(&program_id, &request, &lane_key, 0);

        // The fixed token-program address and executable bit are insufficient:
        // authenticate that the program is itself owned by a supported loader,
        // and reject before either verifier execution or custody CPI.
        let token_program_index = accounts.len() - 1;
        append_test_verifier_checkpoint(&mut accounts);
        accounts[token_program_index].owner = native_loader::id();
        let invalid_loader_before = accounts
            .iter()
            .map(|account| account.data.clone())
            .collect::<Vec<_>>();
        let infos: Vec<_> = accounts.iter_mut().map(TestAccount::info).collect();
        let mut invalid_loader_cpi = WithdrawalCpi {
            fail: false,
            calls: 0,
        };
        assert_eq!(
            process_pair_forest_terminal_with_verifier_v1(
                &program_id,
                &infos,
                &instruction,
                1,
                &Rent::default(),
                &mut invalid_loader_cpi,
                |_, _, _, _, _, _, _, _, _, _, _| panic!("invalid loader reached verifier"),
                |_| {},
            ),
            Err(PoolV1ProgramError::InvalidTokenProgram.into()),
        );
        drop(infos);
        assert_eq!(invalid_loader_cpi.calls, 0);
        assert_eq!(
            accounts
                .iter()
                .map(|account| account.data.clone())
                .collect::<Vec<_>>(),
            invalid_loader_before,
        );
        accounts[token_program_index].owner = bpf_loader::id();

        // B4-style Pool-only vault hints: every wrong authority or vault
        // token bump rejects with the existing custody address errors before
        // the verifier or any CPI.
        let hint_start = instruction.len() - POOL_V1_PAIR_FOREST_TERMINAL_BUMP_HINT_BYTES;
        let mut vault_rejections = 0;
        for (offset, expected) in [
            (2usize, PoolV1ProgramError::InvalidVaultAuthority),
            (3, PoolV1ProgramError::InvalidVaultTokenAddress),
        ] {
            let canonical = instruction[hint_start + offset];
            assert_ne!(canonical, 0);
            for bump in 0..=255u8 {
                if bump == canonical {
                    continue;
                }
                let mut data = instruction.clone();
                data[hint_start + offset] = bump;
                assert_eq!(
                    reject_before_cpi(&program_id, &mut accounts, &data),
                    Err(expected.into()),
                    "vault hint {offset} bump {bump}"
                );
                vault_rejections += 1;
            }
        }
        assert_eq!(vault_rejections, 510);

        let before = accounts
            .iter()
            .map(|account| account.data.clone())
            .collect::<Vec<_>>();
        let infos: Vec<_> = accounts.iter_mut().map(TestAccount::info).collect();
        let mut failing = WithdrawalCpi {
            fail: true,
            calls: 0,
        };
        assert!(process_pair_forest_terminal_with_verifier_v1(
            &program_id,
            &infos,
            &instruction,
            1,
            &Rent::default(),
            &mut failing,
            |_, _, _, _, _, _, _, _, _, _, _| Ok(AuthenticatedPairForestResultV1::for_test(result)),
            |_| {},
        )
        .is_err());
        drop(infos);
        assert_eq!(failing.calls, 1);
        assert_eq!(
            accounts.iter().map(|a| a.data.clone()).collect::<Vec<_>>(),
            before
        );

        let infos: Vec<_> = accounts.iter_mut().map(TestAccount::info).collect();
        let mut success = WithdrawalCpi {
            fail: false,
            calls: 0,
        };
        process_pair_forest_terminal_with_verifier_v1(
            &program_id,
            &infos,
            &instruction,
            1,
            &Rent::default(),
            &mut success,
            |_, _, _, _, _, _, _, _, _, _, _| Ok(AuthenticatedPairForestResultV1::for_test(result)),
            |_| {},
        )
        .unwrap();
        drop(infos);
        assert_eq!(success.calls, 1);
        assert_eq!(
            u64::from_le_bytes(accounts[12].data[64..72].try_into().unwrap()),
            75
        );
        assert_eq!(
            u64::from_le_bytes(accounts[13].data[64..72].try_into().unwrap()),
            35
        );
        assert!(accounts[4].data.iter().any(|byte| *byte != 0));
    }
}

files.programs/aspis-pool/src/pair_forest_disp:
//! Compact selected-verifier dispatch for the inactive eight-lane terminal.
//!
//! ASQ8 deliberately carries only registry identity, the Pool program id and
//! the 216-byte payment public input.  The verifier reconstructs the exact
//! ASF8 statement from the canonical read-only master/checkpoint/lane account
//! bytes and the proof-carried candidate afterstate, then returns exact ASR8.

extern crate alloc;

use alloc::{boxed::Box, vec, vec::Vec};

use aspis_statement::pool_v1::{
    decode_pool_v1_pair_forest_terminal_result_v1, encode_pool_v1_pair_forest_terminal_request_v1,
    encode_pool_v1_pair_forest_terminal_result_v1, PoolV1PairForestTerminalRequestV1,
    PoolV1PairForestTerminalResultV1, POOL_V1_PAIR_FOREST_TERMINAL_RESULT_BYTES,
    POOL_V1_PAIR_FOREST_TERMINAL_VERSION,
};
use solana_program::{
    account_info::AccountInfo,
    entrypoint::ProgramResult,
    instruction::{AccountMeta, Instruction},
    program,
    program_error::ProgramError,
    pubkey::Pubkey,
};
use solana_sdk_ids::{bpf_loader, bpf_loader_upgradeable, loader_v4};

#[cfg(not(feature = "r1-split-checkpoint"))]
use crate::pair_dispatch::derive_pair_verifier_account_claim_v1;
use crate::{
    error::PoolV1ProgramError,
    registry::{authenticate_verifier_selection_v1, VerifierSelectionV1},
};

#[derive(Clone, Debug, PartialEq, Eq)]
pub(crate) struct AuthenticatedPairForestResultV1 {
    value: Box<PoolV1PairForestTerminalResultV1>,
    exact_bytes: Box<[u8]>,
}

impl AuthenticatedPairForestResultV1 {
    pub(crate) fn value(&self) -> &PoolV1PairForestTerminalResultV1 {
        &self.value
    }

    pub(crate) fn exact_bytes(&self) -> &[u8] {
        &self.exact_bytes
    }

    #[cfg(test)]
    pub(crate) fn for_test(value: PoolV1PairForestTerminalResultV1) -> Self {
        let exact_bytes =
            aspis_statement::pool_v1::encode_pool_v1_pair_forest_terminal_result_v1(&value)
                .expect("test result must be canonical")
                .to_vec()
                .into_boxed_slice();
        Self {
            value: Box::new(value),
            exact_bytes,
        }
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub(crate) struct PlannedPairForestDispatchV1 {
    selected_verifier: Pubkey,
    request_bytes: Vec<u8>,
}

fn supported_loader(owner: &Pubkey) -> bool {
    owner == &bpf_loader::id()
        || owner == &bpf_loader_upgradeable::id()
        || owner == &loader_v4::id()
}

fn require_verifier_program(account: &AccountInfo<'_>, selected: &Pubkey) -> ProgramResult {
    if account.key != selected
        || !account.executable
        || account.is_signer
        || account.is_writable
        || !supported_loader(account.owner)
    {
        return Err(PoolV1ProgramError::InvalidVerifierProgramAccount.into());
    }
    Ok(())
}

/// R1 buffer ownership does not authenticate the selected verifier. Registry
/// selection still does that; only its separate checkpoint must be owned by it.
fn proof_transport_verifier(
    verifier_program: &AccountInfo<'_>,
    proof: &AccountInfo<'_>,
    verifier_checkpoint: Option<&AccountInfo<'_>>,
) -> Result<Pubkey, ProgramError> {
    #[cfg(feature = "r1-split-checkpoint")]
    {
        let checkpoint = verifier_checkpoint.ok_or(ProgramError::NotEnoughAccountKeys)?;
        if proof.key == verifier_program.key
            || proof.executable
            || proof.is_signer
            || proof.is_writable
            || checkpoint.owner != verifier_program.key
            || checkpoint.executable
            || checkpoint.is_signer
            || checkpoint.is_writable
            || checkpoint.key == proof.key
            || checkpoint.key == verifier_program.key
        {
            return Err(PoolV1ProgramError::InvalidVerifierProofAccount.into());
        }
        // The verifier checks the exact checkpoint size and authenticated bytes.
        Ok(*verifier_program.key)
    }
    #[cfg(not(feature = "r1-split-checkpoint"))]
    {
        if verifier_checkpoint.is_some() {
            return Err(ProgramError::InvalidArgument);
        }
        let claim = derive_pair_verifier_account_claim_v1(verifier_program, proof)?;
        Ok(Pubkey::new_from_array(claim.verifier_program))
    }
}

fn require_checkpoint_distinct(
    verifier_checkpoint: Option<&AccountInfo<'_>>,
    master: &AccountInfo<'_>,
    forest_checkpoint: &AccountInfo<'_>,
    lane: &AccountInfo<'_>,
    registry_accounts: &[AccountInfo<'_>],
) -> ProgramResult {
    if let Some(checkpoint) = verifier_checkpoint {
        if [master.key, forest_checkpoint.key, lane.key].contains(&checkpoint.key)
            || registry_accounts
                .iter()
                .any(|account| account.key == checkpoint.key)
        {
            return Err(ProgramError::InvalidArgument);
        }
    }
    Ok(())
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn plan_pair_forest_terminal_dispatch_v1(
    pool_program: &Pubkey,
    master: &AccountInfo<'_>,
    checkpoint: &AccountInfo<'_>,
    lane: &AccountInfo<'_>,
    policy: &aspis_statement::pool_v1::VerifierPolicyV1,
    registry_accounts: &[AccountInfo<'_>],
    verifier_program: &AccountInfo<'_>,
    proof: &AccountInfo<'_>,
    verifier_checkpoint: Option<&AccountInfo<'_>>,
    request: &PoolV1PairForestTerminalRequestV1,
    current_slot: u64,
) -> Result<PlannedPairForestDispatchV1, ProgramError> {
    let request_bytes = encode_pool_v1_pair_forest_terminal_request_v1(request)
        .map_err(|_| ProgramError::InvalidInstructionData)?
        .to_vec();
    plan_pair_forest_terminal_dispatch_with_bytes_v1(
        pool_program,
        master,
        checkpoint,
        lane,
        policy,
        registry_accounts,
        verifier_program,
        proof,
        verifier_checkpoint,
        request,
        current_slot,
        request_bytes,
    )
}

#[allow(clippy::too_many_arguments)]
fn plan_pair_forest_terminal_dispatch_with_bytes_v1(
    pool_program: &Pubkey,
    master: &AccountInfo<'_>,
    checkpoint: &AccountInfo<'_>,
    lane: &AccountInfo<'_>,
    policy: &aspis_statement::pool_v1::VerifierPolicyV1,
    registry_accounts: &[AccountInfo<'_>],
    verifier_program: &AccountInfo<'_>,
    proof: &AccountInfo<'_>,
    verifier_checkpoint: Option<&AccountInfo<'_>>,
    request: &PoolV1PairForestTerminalRequestV1,
    current_slot: u64,
    request_bytes: Vec<u8>,
) -> Result<PlannedPairForestDispatchV1, ProgramError> {
    if request.pool_program != pool_program.to_bytes() {
        return Err(PoolV1ProgramError::VerifierDispatchIdentityMismatch.into());
    }
    let selected = proof_transport_verifier(verifier_program, proof, verifier_checkpoint)?;
    require_verifier_program(verifier_program, &selected)?;
    require_checkpoint_distinct(
        verifier_checkpoint,
        master,
        checkpoint,
        lane,
        registry_accounts,
    )?;
    let authenticated = authenticate_verifier_selection_v1(
        master.key,
        policy,
        registry_accounts,
        VerifierSelectionV1 {
            verifier_program: selected.to_bytes(),
            profile_binding: request.verifier_profile,
            release_binding: request.verifier_release,
            statement_version: POOL_V1_PAIR_FOREST_TERMINAL_VERSION,
        },
        current_slot,
    )?;
    if !authenticated.matches_verifier_owner(verifier_program.owner) {
        return Err(PoolV1ProgramError::InvalidVerifierProgramAccount.into());
    }
    if !authenticated.matches(
        master.key.to_bytes(),
        selected.to_bytes(),
        request.verifier_profile,
        request.verifier_release,
        POOL_V1_PAIR_FOREST_TERMINAL_VERSION,
    ) {
        return Err(PoolV1ProgramError::VerifierSelectionMismatch.into());
    }
    let account_keys = [proof.key, master.key, checkpoint.key, lane.key];
    for (index, key) in account_keys.iter().enumerate() {
        if account_keys[..index].iter().any(|previous| previous == key) {
            return Err(ProgramError::InvalidArgument);
        }
    }
    if master.owner != pool_program
        || master.executable
        || master.is_signer
        || checkpoint.owner != pool_program
        || checkpoint.executable
        || checkpoint.is_signer
        || lane.owner != pool_program
        || lane.executable
        || lane.is_signer
    {
        return Err(ProgramError::InvalidAccountData);
    }
    Ok(PlannedPairForestDispatchV1 {
        selected_verifier: selected,
        request_bytes,
    })
}

trait PairForestVerifierRuntimeV1 {
    fn clear_return_data(&mut self);
    fn invoke(
        &mut self,
        instruction: &Instruction,
        account_infos: &[AccountInfo<'_>],
    ) -> ProgramResult;
    fn get_return_data(&mut self) -> Option<(Pubkey, Vec<u8>)>;
}

struct SolanaPairForestVerifierRuntimeV1;

impl PairForestVerifierRuntimeV1 for SolanaPairForestVerifierRuntimeV1 {
    fn clear_return_data(&mut self) {
        program::set_return_data(&[]);
    }

    fn invoke(
        &mut self,
        instruction: &Instruction,
        account_infos: &[AccountInfo<'_>],
    ) -> ProgramResult {
        program::invoke(instruction, account_infos)
    }

    fn get_return_data(&mut self) -> Option<(Pubkey, Vec<u8>)> {
        program::get_return_data()
    }
}

fn invoke_pair_forest_terminal_with_runtime_v1<'info, R: PairForestVerifierRuntimeV1>(
    plan: PlannedPairForestDispatchV1,
    proof: &AccountInfo<'info>,
    master: &AccountInfo<'info>,
    checkpoint: &AccountInfo<'info>,
    lane: &AccountInfo<'info>,
    registry_accounts: &[AccountInfo<'info>],
    verifier_program: &AccountInfo<'info>,
    verifier_checkpoint: Option<&AccountInfo<'info>>,
    runtime: &mut R,
) -> Result<AuthenticatedPairForestResultV1, ProgramError> {
    require_verifier_program(verifier_program, &plan.selected_verifier)?;
    #[cfg(feature = "r1-split-checkpoint")]
    proof_transport_verifier(verifier_program, proof, verifier_checkpoint)?;
    #[cfg(not(feature = "r1-split-checkpoint"))]
    {
        if proof.owner != &plan.selected_verifier || proof.is_writable || proof.is_signer {
            return Err(PoolV1ProgramError::InvalidVerifierProofAccount.into());
        }
        if verifier_checkpoint.is_some() {
            return Err(ProgramError::InvalidArgument);
        }
    }
    require_checkpoint_distinct(
        verifier_checkpoint,
        master,
        checkpoint,
        lane,
        registry_accounts,
    )?;
    #[cfg(feature = "pair-forest-verifier-lane-invariant-audit")]
    let [registry, entry] = registry_accounts
    else {
        return Err(if registry_accounts.len() < 2 {
            ProgramError::NotEnoughAccountKeys
        } else {
            ProgramError::InvalidArgument
        });
    };
    #[cfg(feature = "pair-forest-verifier-lane-invariant-audit")]
    let mut cpi_accounts = vec![
        AccountMeta::new_readonly(*proof.key, false),
        AccountMeta::new_readonly(*master.key, false),
        AccountMeta::new_readonly(*checkpoint.key, false),
        AccountMeta::new_readonly(*lane.key, false),
        AccountMeta::new_readonly(*registry.key, false),
        AccountMeta::new_readonly(*entry.key, false),
    ];
    #[cfg(not(feature = "pair-forest-verifier-lane-invariant-audit"))]
    let mut cpi_accounts = vec![
        AccountMeta::new_readonly(*proof.key, false),
        AccountMeta::new_readonly(*master.key, false),
        AccountMeta::new_readonly(*checkpoint.key, false),
        AccountMeta::new_readonly(*lane.key, false),
    ];
    if let Some(checkpoint) = verifier_checkpoint {
        cpi_accounts.push(AccountMeta::new_readonly(*checkpoint.key, false));
    }
    let instruction = Instruction {
        program_id: plan.selected_verifier,
        accounts: cpi_accounts,
        data: plan.request_bytes,
    };
    #[cfg(feature = "pair-forest-verifier-lane-invariant-audit")]
    let mut infos = vec![
        proof.clone(),
        master.clone(),
        checkpoint.clone(),
        lane.clone(),
        registry.clone(),
        entry.clone(),
        verifier_program.clone(),
    ];
    #[cfg(not(feature = "pair-forest-verifier-lane-invariant-audit"))]
    let mut infos = vec![
        proof.clone(),
        master.clone(),
        checkpoint.clone(),
        lane.clone(),
        verifier_program.clone(),
    ];
    if let Some(checkpoint) = verifier_checkpoint {
        infos.insert(infos.len() - 1, checkpoint.clone());
    }
    runtime.clear_return_data();
    runtime.invoke(&instruction, &infos)?;
    let (returned_program, returned_data) = runtime
        .get_return_data()
        .ok_or(PoolV1ProgramError::MissingVerifierReturnData)?;
    if returned_program != plan.selected_verifier {
        return Err(PoolV1ProgramError::InvalidVerifierReturnProgram.into());
    }
    if returned_data.len() != POOL_V1_PAIR_FOREST_TERMINAL_RESULT_BYTES {
        return Err(PoolV1ProgramError::InvalidVerifierReturnData.into());
    }
    let result = decode_pool_v1_pair_forest_terminal_result_v1(&returned_data)
        .map_err(|_| PoolV1ProgramError::InvalidVerifierReturnData)?;
    Ok(AuthenticatedPairForestResultV1 {
        value: Box::new(result),
        exact_bytes: returned_data.into_boxed_slice(),
    })
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn dispatch_pair_forest_terminal_readonly_v1<'info>(
    pool_program: &Pubkey,
    master: &AccountInfo<'info>,
    checkpoint: &AccountInfo<'info>,
    lane: &AccountInfo<'info>,
    policy: &aspis_statement::pool_v1::VerifierPolicyV1,
    registry_accounts: &[AccountInfo<'info>],
    verifier_program: &AccountInfo<'info>,
    proof: &AccountInfo<'info>,
    verifier_checkpoint: Option<&AccountInfo<'info>>,
    request: &PoolV1PairForestTerminalRequestV1,
    current_slot: u64,
) -> Result<AuthenticatedPairForestResultV1, ProgramError> {
    let plan = plan_pair_forest_terminal_dispatch_v1(
        pool_program,
        master,
        checkpoint,
        lane,
        policy,
        registry_accounts,
        verifier_program,
        proof,
        verifier_checkpoint,
        request,
        current_slot,
    )?;
    let mut runtime = SolanaPairForestVerifierRuntimeV1;
    invoke_pair_forest_terminal_with_runtime_v1(
        plan,
        proof,
        master,
        checkpoint,
        lane,
        registry_accounts,
        verifier_program,
        verifier_checkpoint,
        &mut runtime,
    )
}

/// Audit-only full-statement CPI transport. Registry/profile/release and all
/// account checks are identical to ASQ8; only the exact verifier instruction
/// bytes differ.
#[cfg(feature = "pair-forest-full-asf8-audit")]
#[allow(clippy::too_many_arguments)]
pub(crate) fn dispatch_pair_forest_terminal_full_asf8_readonly_v1<'info>(
    pool_program: &Pubkey,
    master: &AccountInfo<'info>,
    checkpoint: &AccountInfo<'info>,
    lane: &AccountInfo<'info>,
    policy: &aspis_statement::pool_v1::VerifierPolicyV1,
    registry_accounts: &[AccountInfo<'info>],
    verifier_program: &AccountInfo<'info>,
    proof: &AccountInfo<'info>,
    verifier_checkpoint: Option<&AccountInfo<'info>>,
    request: &PoolV1PairForestTerminalRequestV1,
    current_slot: u64,
    statement_bytes: &[u8],
) -> Result<AuthenticatedPairForestResultV1, ProgramError> {
    if statement_bytes.len()
        != aspis_statement::pool_v1::POOL_V1_PAIR_FOREST_TERMINAL_STATEMENT_BYTES
        || !statement_bytes
            .starts_with(&aspis_statement::pool_v1::POOL_V1_PAIR_FOREST_TERMINAL_STATEMENT_MAGIC)
    {
        return Err(ProgramError::InvalidInstructionData);
    }
    let plan = plan_pair_forest_terminal_dispatch_with_bytes_v1(
        pool_program,
        master,
        checkpoint,
        lane,
        policy,
        registry_accounts,
        verifier_program,
        proof,
        verifier_checkpoint,
        request,
        current_slot,
        statement_bytes.to_vec(),
    )?;
    let mut runtime = SolanaPairForestVerifierRuntimeV1;
    invoke_pair_forest_terminal_with_runtime_v1(
        plan,
        proof,
        master,
        checkpoint,
        lane,
        registry_accounts,
        verifier_program,
        verifier_checkpoint,
        &mut runtime,
    )
}

