            &program_id,
            &pool_key,
            &marker_a.canonical_nullifier_encoding(),
        )
        .unwrap()
        .0;
        let mut marker_a_data =
            [0u8; aspis_statement::pool_v1::POOL_V1_NULLIFIER_MARKER_ACCOUNT_BYTES];
        let mut marker_a_lamports = 1;
        let returned = RefCell::new(Vec::new());
        {
            let accounts = vec![
                account(
                    &pool_key,
                    &program_id,
                    &mut pool_lamports,
                    &mut pool_data,
                    true,
                    false,
                ),
