                    &mut marker_a_lamports,
                    &mut marker_a_data,
                    true,
                    false,
                ),
                account(
                    &registry_key,
                    &program_id,
                    &mut registry_lamports,
                    &mut registry_data,
                    false,
                    false,
                ),
                account(
                    &entry_key,
                    &program_id,
                    &mut entry_lamports,
                    &mut entry_data,
                    false,
                    false,
