                    true,
                    false,
                ),
                account(
                    &registry_key,
                    &program_id,
                    &mut registry_lamports,
                    &mut registry_data,
                    false,
                    false,
                ),
                account(
                    &entry_key,
                    &program_id,
                    &mut entry_lamports,
                    &mut entry_data,
                    false,
                    false,
                ),
                account(
                    &verifier_key,
                    &loader,
                    &mut verifier_lamports,
                    &mut verifier_data,
                    false,
                    true,
                ),
                account(
                    &proof_key,
                    &verifier_key,
                    &mut proof_lamports,
                    &mut proof_data,
                    false,
                    false,
                ),
            ];
            process_pair_private_transfer_with_verifier_v1(
                &program_id,
                &accounts,
                &instruction_b,
                21,
                sha256,
                |_, _, _, _, _, _, _, _, _, _| {
                    Ok(authenticated_afterstate(&expected_b, &verifier_key))
                },
                |_| {},
            )
            .unwrap();
        }
        let after_b =
            PairPoolStateV1::decode_from_program_invariant(&pool_data, &pool_key).unwrap();
        assert_eq!(after_b.current_root_sequence(), 2);
        assert_eq!(
            u16::from_le_bytes(history_data[56..58].try_into().unwrap()),
            3
        );

        // Exact replay rejects before verifier dispatch and changes nothing.
        let pool_before = pool_data;
        let history_before = history_data;
        let marker_before = marker_b_data;
        {
            let accounts = vec![
                account(
                    &pool_key,
                    &program_id,
                    &mut pool_lamports,
                    &mut pool_data,
                    true,
                    false,
                ),
                account(
                    &history_key,
                    &program_id,
                    &mut history_lamports,
                    &mut history_data,
                    true,
                    false,
                ),
                account(
                    &marker_b_key,
                    &program_id,
                    &mut marker_b_lamports,
                    &mut marker_b_data,
                    true,
                    false,
                ),
                account(
                    &registry_key,
                    &program_id,
                    &mut registry_lamports,
                    &mut registry_data,
                    false,
                    false,
                ),
                account(
                    &entry_key,
                    &program_id,
                    &mut entry_lamports,
                    &mut entry_data,
                    false,
                    false,
                ),
                account(
                    &verifier_key,
                    &loader,
                    &mut verifier_lamports,
                    &mut verifier_data,
                    false,
                    true,
                ),
                account(
                    &proof_key,
                    &verifier_key,
                    &mut proof_lamports,
                    &mut proof_data,
                    false,
                    false,
                ),
            ];
            assert_eq!(
                process_pair_private_transfer_with_verifier_v1(
                    &program_id,
                    &accounts,
                    &instruction_b,
                    22,
                    sha256,
                    |_, _, _, _, _, _, _, _, _, _| panic!("replay reached verifier"),
                    |_| {},
                ),
                Err(PoolV1ProgramError::NullifierAlreadyConsumed.into())
            );
        }
        assert_eq!(pool_data, pool_before);
        assert_eq!(history_data, history_before);
        assert_eq!(marker_b_data, marker_before);

        // A stale proof-carried afterstate with a fresh marker leaves all
        // state byte-exact.
        let nullifier_c = digest(700);
        let instruction_c = instruction(
            pool_key,
            domain,
            0,
            genesis_root,
            nullifier_c,
            digest(800),
            digest(900),
        );
        let marker_c = PoolV1NullifierMarkerV1::from_historical_anchor(
            &decode_pair_private_transfer_instruction_v1(&instruction_c)
                .unwrap()
                .envelope,
        );
        let marker_c_key = pool_v1_nullifier_marker_address(
            &program_id,
            &pool_key,
            &marker_c.canonical_nullifier_encoding(),
        )
        .unwrap()
        .0;
        let mut marker_c_data =
            [0u8; aspis_statement::pool_v1::POOL_V1_NULLIFIER_MARKER_ACCOUNT_BYTES];
        let mut marker_c_lamports = 1;
        {
            let accounts = vec![
                account(
                    &pool_key,
                    &program_id,
                    &mut pool_lamports,
                    &mut pool_data,
                    true,
                    false,
                ),
                account(
                    &history_key,
                    &program_id,
                    &mut history_lamports,
                    &mut history_data,
                    true,
                    false,
                ),
                account(
                    &marker_c_key,
                    &program_id,
                    &mut marker_c_lamports,
                    &mut marker_c_data,
                    true,
                    false,
                ),
                account(
                    &registry_key,
                    &program_id,
                    &mut registry_lamports,
                    &mut registry_data,
                    false,
                    false,
                ),
                account(
                    &entry_key,
                    &program_id,
                    &mut entry_lamports,
                    &mut entry_data,
                    false,
                    false,
                ),
                account(
                    &verifier_key,
                    &loader,
                    &mut verifier_lamports,
                    &mut verifier_data,
                    false,
                    true,
                ),
                account(
                    &proof_key,
                    &verifier_key,
                    &mut proof_lamports,
                    &mut proof_data,
                    false,
                    false,
                ),
            ];
            assert_eq!(
                process_pair_private_transfer_with_verifier_v1(
                    &program_id,
                    &accounts,
                    &instruction_c,
                    23,
                    sha256,
                    |_, _, _, _, _, _, _, _, _, _| {
                        Ok(authenticated_afterstate(&expected_a, &verifier_key))
                    },
                    |_| {},
                ),
                Err(PoolV1ProgramError::StateHistoryMismatch.into())
            );
        }
        assert_eq!(pool_data, pool_before);
        assert_eq!(history_data, history_before);
        assert!(marker_c_data.iter().all(|byte| *byte == 0));
    }

